    <div id="end-screen" style="position: absolute; inset: 0; background: rgba(15, 23, 42, 0.95); z-index: 20; display: flex; flex-direction: column; align-items: center; justify-content: center; opacity: 0; pointer-events: none; transition: opacity 0.5s;">
        <div style="font-size: 50px; margin-bottom: 20px; animation: bounce 2s infinite;">🎵</div>
