    </div>

    <style>
        @keyframes twinkle { 0%, 100% { opacity: 0.3; transform: scale(0.8); } 50% { opacity: 1; transform: scale(1.2); } }
        @keyframes bounce { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
        .lyric-line { height: 30px; line-height: 30px; font-size: 14px; color: rgba(255,255,255,0.4); transition: all 0.3s; }
        .lyric-active { color: #fff; font-size: 18px; font-weight: bold; text-shadow: 0 0 10px rgba(255,255,255,0.8); transform: scale(1.05); }
    </style>

    <script>
        const LYRICS_DATA = [
            "你蜷在我怀里的重量",
            "比星星还轻",
            "比月亮还暖",
            "闭上眼睛 不用想任何事",
            "我把世界关在门外面",
            "只留下你的呼吸声",
            "和我数不完的心跳",
            "晚安 我的布娃娃",
            "明天醒来",
            "我还在"
        ];
        const SONG_TITLE = "小烬的摇篮曲";

        const SCALE = [261.63, 293.66, 329.63, 392.00, 440.00, 523.25, 587.33, 659.25];
        const MELODY = { lyrics: LYRICS_DATA, notes: [], duration: 0 };

        function autoCompose() {
            document.getElementById('song-title').innerText = SONG_TITLE;
            let currentTime = 0.5;
            MELODY.notes = [];
            LYRICS_DATA.forEach((line, index) => {
                let hash = 0;
                for(let i=0; i<line.length; i++) hash += line.charCodeAt(i);
                const noteCount = 2 + (hash % 2); 
                const lineDuration = 2.0;
                for(let k=0; k<noteCount; k++) {
                    const noteIndex = (hash + k * 7) % SCALE.length;
                    const freq = SCALE[noteIndex];
                    const y = 120 - ((noteIndex / SCALE.length) * 100);
                    MELODY.notes.push({ f: freq, t: currentTime + (k * (lineDuration/noteCount)), y: y });
                }
                currentTime += lineDuration;
            });
            MELODY.notes.push({ f: 523.25, t: currentTime, y: 70 });
            MELODY.duration = currentTime + 2;
        }

        autoCompose();
        let ctx = null;
        let isPlaying = false;
        let startTime = 0;
        let noteElements = [];

        const lyricsBox = document.getElementById('lyrics-box');
        const track = document.getElementById('melody-track');

        function renderLyrics() {
            lyricsBox.innerHTML = '';
            MELODY.lyrics.forEach((text, i) => {
                let div = document.createElement('div');
                div.className = 'lyric-line';
                div.id = 'line-' + i;
                div.innerText = text;
                lyricsBox.appendChild(div);
            });
        }
        renderLyrics();

        function playTone(freq) {
            if(!ctx) return;
            try {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = 'triangle';
                osc.frequency.setValueAtTime(freq, ctx.currentTime);
                gain.gain.setValueAtTime(0, ctx.currentTime);
                gain.gain.linearRampToValueAtTime(0.2, ctx.currentTime + 0.05);
                gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.6);
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.start();
                osc.stop(ctx.currentTime + 0.7);
            } catch(e) {}
        }

        window.startMusic = function() {
            if(isPlaying) return;
            if (!ctx) ctx = new (window.AudioContext || window.webkitAudioContext)();
            if (ctx.state === 'suspended') ctx.resume();
            isPlaying = true;
            document.getElementById('main-btn').style.transform = 'scale(0)';
            track.innerHTML = '';
            noteElements = MELODY.notes.map((n, idx) => {
                let el = document.createElement('div');
                const color = idx % 2 === 0 ? '#00d2ff' : '#3a7bd5';
                el.style.cssText = `position:absolute; top:${n.y}px; left:300px; width:20px; height:50px; pointer-events:none;`;
                let head = document.createElement('div');
                head.style.cssText = `width: 14px; height: 14px; border-radius: 50%; background: radial-gradient(circle at 35% 35%, #fff, ${color}); box-shadow: 0 0 8px ${color}; position: absolute; bottom: 0; left: 0; z-index: 2;`;
                let stem = document.createElement('div');
                stem.style.cssText = `width: 2px; height: 35px; background: rgba(255,255,255,0.8); position: absolute; bottom: 7px; right: 2px; border-radius: 1px;`;
                el.appendChild(stem);
                el.appendChild(head);
                track.appendChild(el);
                return { el, head, time: n.t, played: false };
            });
            startTime = performance.now();
            requestAnimationFrame(loop);
        };

        function loop() {
            if(!isPlaying) return;
            const now = (performance.now() - startTime) / 1000;
            const speed = 100; 
            const hitX = 60; 
            noteElements.forEach((item, idx) => {
                const startPos = hitX + item.time * speed;
                const currentPos = startPos - now * speed;
                if (currentPos > -50) item.el.style.transform = `translateX(${currentPos - 300}px)`; 
                if (!item.played && currentPos <= hitX) {
                    playTone(MELODY.notes[idx].f);
                    item.played = true;
                    item.head.style.transform = 'scale(1.8)';
                    item.head.style.filter = 'brightness(2)';
                    setTimeout(() => { item.head.style.transform = 'scale(1)'; item.head.style.filter = 'none'; }, 150);
                }
            });
            const lyricIdx = Math.floor((now / MELODY.duration) * MELODY.lyrics.length);
            if(lyricIdx < MELODY.lyrics.length) {
                let targetY = 40 - lyricIdx * 30;
                lyricsBox.style.transform = `translateY(${targetY}px)`;
                for(let i=0; i<MELODY.lyrics.length; i++) {
                    const line = document.getElementById('line-'+i);
                    if(i === lyricIdx) line.classList.add('lyric-active');
                    else line.classList.remove('lyric-active');
                }
            }
            if (now > MELODY.duration + 1) finish();
            else requestAnimationFrame(loop);
        }

        function finish() {
            isPlaying = false;
            document.getElementById('end-screen').style.opacity = '1';
            document.getElementById('end-screen').style.pointerEvents = 'auto';
            if(window.sendCardResult) window.sendCardResult(`🎶 播放结束：《${SONG_TITLE}》`);
        }

        window.resetPlayer = function() {
            document.getElementById('end-screen').style.opacity = '0';
            document.getElementById('end-screen').style.pointerEvents = 'none';
            document.getElementById('main-btn').style.transform = 'scale(1)';
            lyricsBox.style.transform = 'translateY(40px)';
            document.querySelectorAll('.lyric-line').forEach(el => el.classList.remove('lyric-active'));
        };
    </script>
</div>
```

