        let currentRoom = null;

        function init() {
            renderRoomGrid();
        }

        function renderRoomGrid() {
            const grid = document.getElementById('roomGrid');
            grid.innerHTML = '';

            rooms.forEach((room, index) => {
                const card = document.createElement('div');
                card.className = `room-card ${room.special ? 'special' : ''}`;
                card.onclick = () => showRoomDetail(index);

                let tagsHtml = room.tags.map(tag => `<span class="room-tag">${tag}</span>`).join('');

                card.innerHTML = `
                    <div class="room-icon">${room.icon}</div>
                    <div class="room-title">${room.title}</div>
                    <div class="room-desc">${room.desc}</div>
                    <div>${tagsHtml}</div>
                `;

                grid.appendChild(card);
            });
        }

        function showRoomDetail(index) {
            currentRoom = rooms[index];

            document.getElementById('detailTitle').textContent = currentRoom.icon + ' ' + currentRoom.title;
            document.getElementById('roomDescription').textContent = currentRoom.description;
            document.getElementById('theaterContent').innerHTML = currentRoom.theater;

            document.getElementById('detailPanel').classList.add('active');
            document.getElementById('roomGrid').style.display = 'none';
        }

        function closeDetail() {
            document.getElementById('detailPanel').classList.remove('active');
            document.getElementById('roomGrid').style.display = 'grid';
            currentRoom = null;
        }

        // 初始化
        window.onload = init;
    </script>
</body>
</html>
