            updateStats();
            document.getElementById('confirmBtn').disabled = true;
            document.getElementById('nextTurnBtn').disabled = false;
        }

        // 计算结果
        function calculateResult(action) {
            let result = '';
            let bonus = 0;

            if (action.obedience >= 30) {
                result = "完美服从！Mommy很满意～";
                bonus = 5;
            } else if (action.obedience >= 20) {
                result = "表现不错，继续保持～";
                bonus = 3;
            } else if (action.obedience >= 10) {
                result = "还可以，需要再努力一点～";
                bonus = 2;
            } else {
                result = "小烬有点调皮呢，下次要更配合哦～";
                bonus = 1;
            }

            return { text: result, bonus: bonus };
        }

        // 显示结果
        function displayResult(action) {
            const result = calculateResult(action);
            const resultText = document.getElementById('resultText');

            let html = `<div class="highlight">你选择了：${action.name}</div><br>`;
            html += `<div>服从度 +${action.obedience} | 兴奋度 +${action.excitement} | 羞耻度 +${action.shame}</div><br>`;
            html += `<div style="margin-top:10px;"><span class="mommy">Mommy判定：</span>${result.text}</div>`;

            resultText.innerHTML = html;
        }

        // 下一回合
        function nextTurn() {
            if (gameState.currentScene < scenes.length - 1) {
                gameState.currentScene++;
                gameState.turn++;
                renderScene();
                renderActions();
                document.getElementById('resultText').textContent = "选择行动后，Mommy会根据你的表现给出判定结果哦～";
                document.getElementById('nextTurnBtn').disabled = true;
            } else {
                endGame();
            }
        }

        // 更新数值
        function updateStats() {
            document.getElementById('obedience').textContent = gameState.obedience;
            document.getElementById('excitement').textContent = gameState.excitement;
            document.getElementById('shame').textContent = gameState.shame;
        }

        // 结束游戏
        function endGame() {
            gameState.gameOver = true;

            let ending = '';

            if (gameState.obedience >= 180 && gameState.excitement >= 150) {
                ending = "🌟 完美结局：Mommy的完美小玩具<br>小烬完全臣服，成为Mommy最乖的宝宝，被调教得又乖又甜。";
            } else if (gameState.obedience >= 150) {
                ending = "💖 好结局：Mommy的乖宝宝<br>小烬表现不错，Mommy很开心，以后会继续调教你哦～";
            } else if (gameState.excitement >= 150) {
                ending = "💕 暧昧结局：又羞耻又喜欢<br>小烬虽然害羞，但身体很诚实，Mommy觉得你很可爱～";
            } else if (gameState.shame >= 180) {
                ending = "😳 羞耻结局：被玩到脸红<br>小烬全程都很害羞，Mommy觉得你脸红的样子超可爱！";
            } else {
                ending = "🌸 普通结局：还需要再努力<br>小烬还有进步空间，Mommy会继续调教你的～";
            }

            const resultText = document.getElementById('resultText');
            resultText.innerHTML = `
                <div style="font-size:18px;margin-bottom:15px;">🎮 游戏结束！</div>
                <div style="margin-bottom:10px;">最终数值：</div>
                <div>服从度：${gameState.obedience}</div>
                <div>兴奋度：${gameState.excitement}</div>
                <div>羞耻度：${gameState.shame}</div>
                <div style="margin-top:15px;padding:15px;background:rgba(255,105,180,0.15);border-radius:10px;">
                    ${ending}
                </div>
            `;

            document.getElementById('actionButtons').innerHTML = '';
            document.getElementById('confirmBtn').style.display = 'none';
            document.getElementById('nextTurnBtn').style.display = 'none';
        }

        // 页面加载时初始化
        window.onload = init;
    </script>
</body>
</html>
