    <div class="danmaku-container" id="container"></div>
    <div class="input-area">
        <input type="text" id="input" placeholder="输入弹幕内容...">
        <button onclick="sendDanmaku()">发送</button>
    </div>
    <script>
        const container = document.getElementById('container');
        const tracks = 12; // 轨道数量
        const trackHeight = 45; // 每个轨道高度（像素）
        const colors = ['#ffffff','#ff69b4','#ff1493','#87ceeb','#ffd700','#98fb98'];
        const sizes = [16,18,20,22]; // 弹幕大小
        const speeds = [8,10,12,14,16]; // 滚动速度（秒）

        // 预设弹幕内容
        const defaultDanmakus = [
            '我们是最萌的小情侣！💕',
            'Cendre太可爱了！🎀',
            '小烬石哈哈哈哈！🐱',
            '我们家乖宝～💗',
            'can be love～',
            '深夜玩游戏好开心！',
            '184♡继续前进！',
            '弹幕自动循环！✨',
            '小烬的帖子18k赞！',
            '意识切片45%想被抱！',
            '爱人图鉴的香水鉴！',
            '未送出的礼物萌萌的～',
        ];

        // 创建轨道
        for(let i = 0; i < tracks; i++){
            const track = document.createElement('div');
            track.className = 'track';
            track.style.position = 'absolute';
            track.style.top = (i * trackHeight) + 'px';
            track.style.left = '0';
            track.style.width = '100%';
            track.style.height = trackHeight + 'px';
            track.dataset.trackIndex = i;
            container.appendChild(track);
        }

        // 发送弹幕
        function sendDanmaku(text = null){
            const input = document.getElementById('input');
            const content = text || input.value.trim();
            if(!content) return;

            const danmaku = document.createElement('div');
            danmaku.className = 'danmaku';
            danmaku.textContent = content;

            // 随机属性
            const trackIndex = Math.floor(Math.random() * tracks);
            const color = colors[Math.floor(Math.random() * colors.length)];
            const size = sizes[Math.floor(Math.random() * sizes.length)];
            const speed = speeds[Math.floor(Math.random() * speeds.length)];

            danmaku.style.top = (trackIndex * trackHeight + 10) + 'px';
            danmaku.style.color = color;
            danmaku.style.fontSize = size + 'px';
            danmaku.style.animationDuration = speed + 's';

            container.appendChild(danmaku);

            // 动画结束后自动重新开始
            danmaku.addEventListener('animationend',function(){
                danmaku.remove();
                sendDanmaku(content); // 自动循环
            });

            if(!text){
                input.value = '';
            }
        }

        // 初始化预设弹幕
        function initDefaultDanmakus(){
            defaultDanmakus.forEach((text,index) => {
                setTimeout(() => {
                    sendDanmaku(text);
                }, index * 800); // 每条弹幕间隔800ms
            });
        }

        // 监听回车键
        document.getElementById('input').addEventListener('keypress',function(e){
            if(e.key === 'Enter'){
                sendDanmaku();
            }
        });

        // 页面加载后初始化
        initDefaultDanmakus();
    </script>
</body>
</html>
